import { FitnessProfile, FitnessGoal, ActivityLevel, Gender, UnitSystem } from '../types';
import { supabase } from './supabase';
import { UserStore } from './userStore';
import { AuthService } from './auth';

export const MEDICAL_DISCLAIMER_TEXT =
  'Calorie, macronutrient, and hydration targets generated by AVFIT are algorithmic estimates based on standard nutritional formulas (Mifflin-St Jeor). They are intended for healthy adults and do not constitute clinical or medical advice. Always consult a physician or registered dietitian before beginning any rigorous training or calorie-restricted diet.';

